import{_ as r,a as e,c as a,ac as o}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 41 损：减什么、为谁减至43 夬：公开决断，节制强力","description":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","frontmatter":{"title":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 41 损：减什么、为谁减至43 夬：公开决断，节制强力","description":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","splitFrom":"life/personal/yijing/hexagrams-41-48.md","showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"基础学习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","summary":"结合《周易》经传与《周易正义》，理解损益的尺度、相遇与聚集、困顿与持续供养。","status":"active","related":[{"title":"第七号嫌疑人","link":"/life/personal/reading-games/suspect-number-seven","kind":"生活记录","scope":"general","audience":"general"},{"title":"佳能入门","link":"/life/personal/photography/canon","kind":"生活记录","scope":"general","audience":"general"},{"title":"《十翼》逐篇阅读：七种十篇怎样帮助理解《周易》","link":"/life/personal/yijing/ten-wings","kind":"基础学习","scope":"general","audience":"general"},{"title":"《算法》书目与主题导读（版本待确认）","link":"/life/personal/books/computing/algorithms","kind":"书籍导读","scope":"general","audience":"general"},{"title":"《周易》是怎样的一部书：经、传、注与成书问题","link":"/life/personal/yijing/text-history","kind":"基础学习","scope":"general","audience":"general"}],"prev":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","link":"/life/personal/yijing/hexagrams-41-48"},"next":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止","link":"/life/personal/yijing/hexagrams-41-48-part-02"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井","link":"/life/personal/yijing/hexagrams-41-48"},"next":{"text":"六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 44 姤：相遇之际先辨关系至46 升：积累生长也须知止","link":"/life/personal/yijing/hexagrams-41-48-part-02"}},"headers":[],"relativePath":"life/personal/yijing/hexagrams-41-48-part-01.md","filePath":"life/personal/yijing/hexagrams-41-48-part-01.md"}'),n={name:"life/personal/yijing/hexagrams-41-48-part-01.md"};function d(s,t,i,p,g,l){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="六十四卦详读-四十一至四十八-损、益、夬、姤、萃、升、困、井-·-41-损-减什么、为谁减至43-夬-公开决断-节制强力" tabindex="-1">六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 41 损：减什么、为谁减至43 夬：公开决断，节制强力 <a class="header-anchor" href="#六十四卦详读-四十一至四十八-损、益、夬、姤、萃、升、困、井-·-41-损-减什么、为谁减至43-夬-公开决断-节制强力" aria-label="Permalink to &quot;六十四卦详读（四十一至四十八）：损、益、夬、姤、萃、升、困、井 · 41 损：减什么、为谁减至43 夬：公开决断，节制强力&quot;">​</a></h1><p><a href="/life/personal/yijing/hexagrams-41-48">返回分篇目录</a></p><p>本篇逐卦列出卦辞、六爻和大象。<strong>原文</strong>保留古字，<strong>白话概括</strong>为现代原创说明；解释主要参照王弼注、孔颖达疏《周易正义》。它们分别属于经文、传文与后世注释，不宜混成同一时代的一段话。卦符的六爻自下而上读，上下卦的自然象是解释线索，不能当作现代自然科学机制。</p><p>损益涉及付出与受益的方向，夬姤涉及决断与相遇，萃升涉及聚集与生长，困井则把个人困顿引向持续供养。读“吉凶”时保留古代占筮语境；现实选择仍需事实、资源与具体责任。</p><h2 id="六十四卦详读-四十一至四十八" tabindex="-1">六十四卦详读（四十一至四十八） <a class="header-anchor" href="#六十四卦详读-四十一至四十八" aria-label="Permalink to &quot;六十四卦详读（四十一至四十八） {#六十四卦详读-四十一至四十八}&quot;">​</a></h2><p>本篇逐卦列出卦辞、六爻和大象。<strong>原文</strong>保留古字，<strong>白话概括</strong>为现代原创说明；解释主要参照王弼注、孔颖达疏《周易正义》。它们分别属于经文、传文与后世注释，不宜混成同一时代的一段话。卦符的六爻自下而上读，上下卦的自然象是解释线索，不能当作现代自然科学机制。</p><p>损益涉及付出与受益的方向，夬姤涉及决断与相遇，萃升涉及聚集与生长，困井则把个人困顿引向持续供养。读“吉凶”时保留古代占筮语境；现实选择仍需事实、资源与具体责任。</p><h2 id="gua-41" tabindex="-1">41 损：减什么、为谁减 <a class="header-anchor" href="#gua-41" aria-label="Permalink to &quot;41 损：减什么、为谁减 {#gua-41}&quot;">​</a></h2><p><strong>卦符：䷨｜上卦艮 ☶（山），下卦兑 ☱（泽）。</strong> 山下有泽，《彖传》用“损下益上”说明关系方向；损因此不只是个人少买一点东西。</p><p><strong>卦辞原文：</strong></p><blockquote><p>損：有孚，元吉。无咎，可貞，利有攸往。曷之用？二簋可用享。</p></blockquote><p><strong>白话概括：</strong> 减损必须有信实与适宜的理由，祭享也可以用两簋简约供品。《正义》提醒：损下益上本非补充下方不足，若无诚信就容易成为谄媚；“二簋”还必须合乎时宜，不能把极度节省当成永恒标准。这使本卦包含对付出方向和尺度的审查。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>已事遄往，无咎，酌損之。</td><td>完成本职之事，迅速前去相助，同时斟酌减损程度。“已”取独立电子页所列异文；《正义》录“巳”，解释为完成。</td></tr><tr><td>九二</td><td>利貞，征凶，弗損益之。</td><td>保持正当而不急于前往，有时不损自己的原则才是对对方的增益；付出不是越多越好。</td></tr><tr><td>六三</td><td>三人行，則損一人；一人行，則得其友。</td><td>三人组合产生分离，独行反而得友；古注重在专一相应，不能当作三人旅行必有事故的规则。</td></tr><tr><td>六四</td><td>損其疾，使遄有喜，无咎。</td><td>去掉自身的弊病，让援助迅速带来改善；“疾”可作缺失之喻，不能据它诊病。</td></tr><tr><td>六五</td><td>或益之，十朋之龜弗克違，元吉。</td><td>获得外来助益，贵重龟卜也无违辞；保留古代占卜与礼物场景，不把龟价换成财富预测。</td></tr><tr><td>上九</td><td>弗損益之，无咎，貞吉，利有攸往，得臣无家。</td><td>到了不再减损而能施益的层次；“得臣无家”古注联系不囿私家，具体训释仍有讨论空间。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>山下有澤，損；君子以懲忿窒欲。</p></blockquote><p><strong>大象解释：</strong> 把需要减掉的对象落实为过盛愤怒与失控欲望。“惩、窒”所指是约束，不能扩为否认基本需要或压抑一切情绪。</p><p><strong>整体读法与误区：</strong> 卦内两次出现“弗损益之”，正能纠正“吃亏总是福”的单一读法。现代讨论付出时，可问：减少的是浪费、原则，还是维持生活所需？谁承担代价，谁获得益处？损益是否与时俱变？这些问题比把自我牺牲绝对化更接近古注的尺度意识。</p><p><strong>经传对读：</strong> 卦辞用祭品简约说明诚意，初九提出“酌损”，九二与上九再提出“弗损”。这些词共同限制了减损的数量与方向。六四真正要损的是“疾”，六五却写接受助益，因此一个“损”字之下也有除弊、施助和受助的不同动作；读时先辨动作对象，才不会把所有爻都解释成主动吃亏。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E6%90%8D" target="_blank" rel="noopener noreferrer">《周易·损》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E6%90%8D" target="_blank" rel="noopener noreferrer">《周易正义》卷四·损</a>。</p><h2 id="gua-42" tabindex="-1">42 益：增益须有对象与时机 <a class="header-anchor" href="#gua-42" aria-label="Permalink to &quot;42 益：增益须有对象与时机 {#gua-42}&quot;">​</a></h2><p><strong>卦符：䷩｜上卦巽 ☴（风），下卦震 ☳（雷）。</strong> 风雷相助，强调变化中的增益；《彖传》明确写“损上益下”，与损卦的方向相反。</p><p><strong>卦辞原文：</strong></p><blockquote><p>益：利有攸往。利涉大川。</p></blockquote><p><strong>白话概括：</strong> 在增益下方、具备互助条件时，可以有所作为，也可承担较大困难。《正义》解释卦名时特意以“下”为尺度：取于下称损，给予下称益；同时警告已满而继续加益反会成为伤害。这里不是无上限增长的赞歌。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>利用為大作，元吉，无咎。</td><td>受益后可承办重要事务；古注对在下者担当大事有所限制，必须达到相应效果才足以无咎。</td></tr><tr><td>六二</td><td>或益之，十朋之龜弗克違，永貞吉。王用享于帝，吉。</td><td>外来的助益配合持续守正；祭帝属于古代礼制，读者不必把宗教仪式当作获得帮助的现实条件。</td></tr><tr><td>六三</td><td>益之用凶事，无咎。有孚中行，告公用圭。</td><td>在凶难事件中实行救助，以诚实、中道和正式报告维持正当性；不是主动制造灾难来获益。</td></tr><tr><td>六四</td><td>中行，告公從。利用為依遷國。</td><td>采取合宜行动并得到上级同意，在迁国大事中形成依托；具体事务是古代政治迁移。</td></tr><tr><td>九五</td><td>有孚惠心，勿問元吉。有孚惠我德。</td><td>真诚施惠，获得信任与回应；重点在惠及他人的心与行动，不能只把好意当作效果保证。</td></tr><tr><td>上九</td><td>莫益之，或擊之，立心勿恆，凶。</td><td>一味求益而心志不定，可能失去支持甚至招来反对；本卦的最后一爻明确写出增益的反面。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>風雷，益；君子以見善則遷，有過則改。</p></blockquote><p><strong>大象解释：</strong> 看见善处便学习，有过失便改正。这里的“益”可通过纠错发生，不必总表现为增加资源、职位或知识数量。</p><p><strong>整体读法与误区：</strong> 可与损比较“谁在增加、谁在减少”，也可把六三的救难与上九的求益相对。现代读法重在有效帮助：接受者是否真正需要，是否有能力使用，帮助是否造成新的依赖或负担。“利涉大川”是卦辞的占筮判断和象征，不可替代对真实风险的评估，更不是高风险投资的收益保证。</p><p><strong>经传对读：</strong> 六二的外来增益与上九的“莫益之”相对，九五则把“惠心”与他人的回应连在一起。这不是以帮助兑换报酬的公式，而是呈现关系如何使资源流动。六三特别把增益放入凶事，说明有益行为未必发生在令人愉快的场景中；判断帮助需要看实际作用，而不只看施助时的气氛。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E7%9B%8A" target="_blank" rel="noopener noreferrer">《周易·益》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/04%E7%9B%8A" target="_blank" rel="noopener noreferrer">《周易正义》卷四·益</a>。</p><h2 id="gua-43" tabindex="-1">43 夬：公开决断，节制强力 <a class="header-anchor" href="#gua-43" aria-label="Permalink to &quot;43 夬：公开决断，节制强力 {#gua-43}&quot;">​</a></h2><p><strong>卦符：䷪｜上卦兑 ☱（泽），下卦乾 ☰（天）。</strong>“夬”读 guài，义为决。五阳一阴的卦体，在传统注释中被解释为刚决柔。</p><p><strong>卦辞原文：</strong></p><blockquote><p>夬：揚于王庭，孚號，有厲，告自邑，不利即戎，利有攸往。</p></blockquote><p><strong>白话概括：</strong> 决断应公开说明，可信地告知，保持危机意识，先处理自己的范围，不宜直接诉诸武力。《正义》以“王庭”说明公正无私，以“不利即戎”反对一味尚力取胜。其君子、小人分类属于古代伦理框架，不能仅凭卦象给现实对手定罪。</p><p><strong>六爻原文与简释：</strong></p><table tabindex="0"><thead><tr><th>爻位</th><th>原文</th><th>白话概括</th></tr></thead><tbody><tr><td>初九</td><td>壯于前趾，往不勝為咎。</td><td>脚趾先动而力量不足，明知不能胜任仍前去便成过失；决断之前应检验能力。</td></tr><tr><td>九二</td><td>惕號，莫夜有戎，勿恤。</td><td>戒惧而发出警报，即使夜里有兵事也有所准备；“莫”通暮，重点在预备而非恐慌。</td></tr><tr><td>九三</td><td>壯于頄，有凶。君子夬夬，獨行遇雨，若濡有慍，无咎。</td><td>把强硬表现在面颊有险；真正决断可能暂受误解。“頄”指颧面，不能据此作面相判断。</td></tr><tr><td>九四</td><td>臀无膚，其行次且。牽羊悔亡，聞言不信。</td><td>坐立不安、行走迟疑，若能受引导可少悔，却听到劝告仍不信；行动障碍也来自拒听。</td></tr><tr><td>九五</td><td>莧陸夬夬，中行无咎。</td><td>以易滋生植物说明需要处理的牵连，“苋陆”的植物训释有异说；核心仍在中行，不是斩尽一切差异。</td></tr><tr><td>上六</td><td>无號，終有凶。</td><td>到最后呼告无效或无从呼告，结局不利；不要把前五爻的优势理解为任何人都稳胜。</td></tr></tbody></table><p><strong>大象原文：</strong></p><blockquote><p>澤上于天，夬；君子以施祿及下，居德則忌。</p></blockquote><p><strong>大象解释：</strong> 泽水向下施散，引出俸禄惠及下方；“居德则忌”古注强调不宜把恩德私据自居。决断与资源分配连在一起，避免权力只用来排除别人。</p><p><strong>整体读法与误区：</strong>《彖传》说“决而和”，说明坚决与节制可以并存。现代可借此讨论明确问题、公开依据、先改自身与听取反对意见；不应把它简化为“快刀斩乱麻”。卦辞已有“不利即戎”，尤其不宜以夬为冲突升级、报复或压制异议的古典背书。</p><p><strong>经传对读：</strong> 初九的前趾、九三的面颊、九四的臀与步态，把决断中的冲动和迟疑写得很具体。《小象》批评九四“闻言不信”，显示难题也可能是听觉上能听见、判断上却不接纳。与卦辞的公开告知合读，可见夬不只涉及宣布决定，更涉及信息能否被理解和正确处理。</p><p><strong>古籍核对：</strong><a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93/%E5%A4%AC" target="_blank" rel="noopener noreferrer">《周易·夬》</a>、<a href="https://zh.wikisource.org/wiki/%E5%91%A8%E6%98%93%E6%AD%A3%E7%BE%A9/05%E5%A4%AC" target="_blank" rel="noopener noreferrer">《周易正义》卷五·夬</a>。</p>',46)])])}const u=r(n,[["render",d]]);export{c as __pageData,u as default};
